function clean(v){return String(v===undefined||v===null?'':v).trim()}

function table(name,headers,opts={}){
  let items=[];
  try{items=$(name).all()}catch{return {rows:[],total:0,truncated:false}}

  const total=items.length;
  if(!total)return {rows:[],total:0,truncated:false};

  const max=Math.max(1,Number(opts.max||total));
  const tail=!!opts.tail;
  const first=(items[0]?.json)||{};
  const direct=headers.every(h=>Object.prototype.hasOwnProperty.call(first,h));
  const rows=[];

  if(direct){
    const from=tail?Math.max(0,total-max):0;
    const to=tail?total:Math.min(total,max);
    for(let i=from;i<to;i++){
      const r=items[i]?.json||{};
      if(headers.every(h=>clean(r[h])===h))continue;
      let nonEmpty=false;
      for(const h of headers){if(clean(r[h])!==''){nonEmpty=true;break}}
      if(nonEmpty)rows.push(r);
    }
    return {rows,total,truncated:total>max};
  }

  // Legacy/header-row fallback. Scan only a small prefix for the header,
  // then bound the data rows so a growing sheet cannot monopolize the task runner.
  const probe=Math.min(total,64);
  let headerIndex=-1, keys=[], heads=[];
  for(let i=0;i<probe;i++){
    const r=items[i]?.json||{};
    const vals=Object.values(r).map(clean);
    if(headers.every(h=>vals.includes(h))){
      headerIndex=i;
      keys=Object.keys(r).filter(k=>k!=='row_number');
      heads=keys.map(k=>clean(r[k]));
      break;
    }
  }
  if(headerIndex<0)return {rows:[],total,truncated:false};

  const dataStart=headerIndex+1;
  const available=Math.max(0,total-dataStart);
  const from=tail?Math.max(dataStart,total-max):dataStart;
  const to=tail?total:Math.min(total,dataStart+max);
  for(let i=from;i<to;i++){
    const r=items[i]?.json||{};
    const o={}; let nonEmpty=false;
    for(let j=0;j<keys.length;j++){
      if(!heads[j])continue;
      const v=r[keys[j]];
      o[heads[j]]=v;
      if(clean(v)!=='')nonEmpty=true;
    }
    if(nonEmpty)rows.push(o);
  }
  return {rows,total:available,truncated:available>max};
}
function fnv(value){
  let h=2166136261;
  for(const ch of String(value)){
    h^=ch.charCodeAt(0);
    h=Math.imul(h,16777619);
  }
  return (h>>>0).toString(16).padStart(8,'0');
}

function priority(score,explicit){
  const p=clean(explicit).toUpperCase();
  if(['A','B','C'].includes(p))return p;
  const n=Number(String(score||0).replace(',','.'));
  return n>=80?'A':n>=55?'B':'C';
}

function safeDecode(value){
  try{return decodeURIComponent(value)}catch{return value}
}

function queryValue(query,key){
  for(const part of String(query||'').split('&')){
    const [rawKey,...rest]=part.split('=');
    if(safeDecode(rawKey||'')===key){
      return safeDecode(rest.join('=')||'');
    }
  }
  return '';
}

function extractUrls(value,platform){
  const input=clean(value);
  if(!input)return[];

  const out=[];
  const rx=/(?:https?:\/\/)?(?:(?:www|m|web)\.)?(?:facebook\.com|fb\.com|instagram\.com)\/[^\s<>"'(),;]+|@[A-Za-z0-9._]{2,}/gi;

  for(let match of (input.match(rx)||[])){
    match=match.replace(/[\]\)}>.,;:!?]+$/g,'');

    if(match.startsWith('@')){
      if(platform==='Instagram'){
        out.push(`https://www.instagram.com/${match.slice(1)}/`);
      }
      continue;
    }

    if(!/^https?:\/\//i.test(match)){
      match='https://'+match;
    }

    out.push(match);
  }

  return [...new Set(out)];
}

/*
 * Parser celowo nie używa globalnego URL/new URL().
 * Dzięki temu działa także w ograniczonym środowisku Code node n8n.
 */
function parseProfile(platform,rawUrl){
  let value=clean(rawUrl).replace(/&amp;/gi,'&');
  if(!value)return {id:'',reason:'EMPTY'};

  if(value.startsWith('@')){
    if(platform!=='Instagram')return {id:'',reason:'HANDLE_WRONG_PLATFORM'};
    const handle=value.slice(1).toLowerCase();
    return /^[a-z0-9._]{2,30}$/i.test(handle)
      ? {id:handle,reason:''}
      : {id:'',reason:'INVALID_HANDLE'};
  }

  value=value
    .replace(/^https?:\/\//i,'')
    .replace(/^\/\//,'')
    .replace(/#.*$/,'');

  const qIndex=value.indexOf('?');
  const beforeQuery=qIndex>=0?value.slice(0,qIndex):value;
  const query=qIndex>=0?value.slice(qIndex+1):'';

  const slashIndex=beforeQuery.indexOf('/');
  let host=(slashIndex>=0?beforeQuery.slice(0,slashIndex):beforeQuery).toLowerCase();
  let path=slashIndex>=0?beforeQuery.slice(slashIndex+1):'';

  host=host
    .replace(/^www\./,'')
    .replace(/^m\./,'')
    .replace(/^web\./,'');

  const parts=path
    .split('/')
    .map(safeDecode)
    .map(x=>x.trim())
    .filter(Boolean);

  if(platform==='Instagram'){
    if(host!=='instagram.com')return {id:'',reason:'WRONG_HOST'};

    const handle=(parts[0]||'').replace(/^@/,'').toLowerCase();
    const reserved=new Set([
      'p','reel','reels','stories','explore','share',
      'accounts','direct','about','developer'
    ]);

    if(!handle)return {id:'',reason:'NO_HANDLE'};
    if(reserved.has(handle))return {id:'',reason:'CONTENT_URL'};
    if(!/^[a-z0-9._]{2,30}$/i.test(handle)){
      return {id:'',reason:'INVALID_HANDLE'};
    }

    return {id:handle,reason:''};
  }

  if(!['facebook.com','fb.com'].includes(host)){
    return {id:'',reason:'WRONG_HOST'};
  }

  const first=(parts[0]||'').toLowerCase();

  if(first==='profile.php'){
    const id=queryValue(query,'id');
    return /^\d{5,25}$/.test(id)
      ? {id,reason:''}
      : {id:'',reason:'PROFILE_WITHOUT_ID'};
  }

  const blocked=new Set([
    'share','groups','events','watch','reel','reels','story.php',
    'photo.php','permalink.php','marketplace','gaming','login',
    'plugins','help','privacy','policies'
  ]);

  if(blocked.has(first)){
    return {id:'',reason:'CONTENT_OR_UNSUPPORTED_URL'};
  }

  const numeric=[...parts].reverse().find(x=>/^\d{5,25}$/.test(x));
  if(numeric)return {id:numeric,reason:''};

  let handle='';
  if(first==='pages'){
    handle=parts[1]||'';
  }else if(first==='pg'){
    handle=parts[1]||'';
  }else if(first==='people'){
    handle=parts[1]||'';
  }else{
    handle=parts[0]||'';
  }

  handle=handle
    .replace(/^@/,'')
    .replace(/[^A-Za-z0-9._-]/g,'');

  if(!handle)return {id:'',reason:'NO_PAGE_HANDLE'};
  return {id:handle.toLowerCase(),reason:''};
}

