const known=new Set(
  existing
    .filter(r=>!clean(r.Target_ID).startsWith('SEED-'))
    .map(r=>`${clean(r.Platform).toLowerCase()}|${clean(r.Object_ID_or_Username).toLowerCase()}`)
    .filter(x=>!x.endsWith('|'))
);

const candidates=[];
const stats={
  extracted_urls:0,
  invalid_urls:0,
  duplicates:0,
  invalid_reasons:{},
  invalid_samples:[]
};

function add(platform,url,name,type,country,city,score,explicitPriority,origin,notes){
  stats.extracted_urls++;

  const parsed=parseProfile(platform,url);
  const objectId=clean(parsed.id);

  if(!objectId){
    stats.invalid_urls++;
    const reason=parsed.reason||'UNKNOWN';
    stats.invalid_reasons[reason]=(stats.invalid_reasons[reason]||0)+1;

    if(stats.invalid_samples.length<15){
      stats.invalid_samples.push({
        platform,
        url,
        name:clean(name),
        reason
      });
    }
    return;
  }

  const key=`${platform.toLowerCase()}|${objectId.toLowerCase()}`;

  if(known.has(key)){
    stats.duplicates++;
    return;
  }

  known.add(key);

  const prefix=platform==='Facebook'?'FB':'IG';

  candidates.push({
    Target_ID:`META-${prefix}-${fnv(key)}`,
    Active:true,
    Platform:platform,
    Entity_Type:clean(type)||'UNKNOWN',
    Name:clean(name)||objectId,
    Object_ID_or_Username:objectId,
    Profile_URL:url,
    Country:clean(country)||'CEE',
    City:clean(city),
    Language:'PL/EN',
    Priority:priority(score,explicitPriority),
    Polling_Minutes:180,
    Credential_Name:'Meta Virya OAuth2',
    Last_Checked_At:'',
    Last_Post_At:'',
    Cursor_or_Since:'',
    Source_Origin:origin,
    Notes:notes,
    Access_Mode:platform==='Facebook'?'PAGE_FEED':'BUSINESS_DISCOVERY',
    API_Status:'NEW',
    Last_Error:''
  });
}

