function clean(v){return String(v===undefined||v===null?'':v).trim()}

function table(name,headers){
  let raw=[];
  try{raw=$(name).all().map(i=>i.json||{})}catch{return[]}

  raw=raw.filter(r=>Object.entries(r).some(([k,v])=>k!=='row_number'&&clean(v)!==''));
  if(!raw.length)return[];

  if(headers.every(h=>Object.prototype.hasOwnProperty.call(raw[0],h))){
    return raw.filter(r=>!headers.every(h=>clean(r[h])===h));
  }

  const idx=raw.findIndex(r=>{
    const vals=Object.values(r).map(clean);
    return headers.every(h=>vals.includes(h));
  });
  if(idx<0)return[];

  const hr=raw[idx];
  const keys=Object.keys(hr).filter(k=>k!=='row_number');
  const heads=keys.map(k=>clean(hr[k]));

  return raw.slice(idx+1)
    .map(r=>{
      const o={};
      keys.forEach((k,j)=>{if(heads[j])o[heads[j]]=r[k]});
      return o;
    })
    .filter(r=>Object.values(r).some(v=>clean(v)!==''));
}

const rows=$('Code — Build target registry').all().map(i=>i.json||{});
const ctrl=rows.find(r=>r.__control);
const targets=rows.filter(r=>!r.__control&&r.Target_ID);

const pod=table('GS — CRM Podmioty',['Nazwa','Facebook','Instagram']);
const zgl=table('GS — CRM Zgloszenia',['Wydarzenie','Facebook','Instagram']);

const now=new Date().toISOString();
const status=ctrl?.run_status||(targets.length?'OK_NEW_TARGETS':'OK_NO_NEW_TARGETS');

return [{
  json:{
    Run_Key:`META15:${now}`,
    Workflow:'VIRYA 15 — META Target Registry',
    Started_At:now,
    Finished_At:now,
    Status:status,
    Input_Count:pod.length+zgl.length,
    Target_Count:targets.length,
    API_OK:0,
    API_Errors:status.startsWith('ERROR')?1:0,
    New_Items:targets.length,
    Filtered_or_Duplicates:Number(ctrl?.duplicates||0),
    Notes:ctrl?.notes||`Dodano ${targets.length} nowych targetów z CRM.`,
    Execution_Mode:'scheduled/manual',
    Trace_JSON:JSON.stringify({
      podmioty:pod.length,
      zgloszenia:zgl.length,
      control:ctrl||null
    }).slice(0,5000)
  }
}];
